-- Mexico deep-dive content: page, stats, file_format cards,
-- scope_transmission cards + lifecycle card ("The clearance flow (timbrado)"),
-- steps, penalties_related cards, portal. No penalty rows/table.

INSERT OR IGNORE INTO deep_dive_pages (country_id, last_updated) SELECT id, '2026-07-21' FROM countries WHERE name_en = 'Mexico';
INSERT OR IGNORE INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro) SELECT id, 'en', 'Centralised clearance (PAC network)', 'This deep-dive page reflects publicly available technical guidance as of July 2026 and is provided for general awareness, not legal or tax advice. Anexo 20 catalogs, complemento specifications, and penalty provisions continue to evolve — confirm current requirements directly with the SAT or your PAC before building an integration.', 'Mexico''s CFDI system is over a decade old — the interesting activity today is version upgrades and annual catalog maintenance, not a fundamental rebuild.', 'Anexo 20 is the master reference — but almost every specific transaction type layers its own additional complemento on top.', 'Mexico''s clearance runs through private, government-authorised certifiers (PACs) rather than a single government portal — closer to France''s PA model than Italy''s SDI.', 'There''s no single "register here" step — compliance runs through your RFC, your e.firma, and your chosen PAC relationship.', '2026''s reform sharpened SAT''s teeth considerably — treat CFDI authenticity as a genuine compliance risk, not just a formatting exercise.' FROM countries WHERE name_en = 'Mexico';

