INSERT OR IGNORE INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'file_format', 0 FROM countries WHERE name_en = 'Mexico';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'en', 'Base specification', '[["Format", "XML, per Anexo 20 of the current Resolución Miscelánea Fiscal"], ["Current version", "CFDI 4.0"], ["Mandatory fields", "RFC (issuer + receiver), fiscal regime, postal code, Uso del CFDI, forma/método de pago"]]', 'Anexo 20 dictates not just which fields are required, but the acceptable values for each — an XML with every required field present can still be rejected if a fiscal regime code is invalid.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'Mexico' AND dc.section = 'file_format' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'file_format', 1 FROM countries WHERE name_en = 'Mexico';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'en', 'Complementos — the real complexity', '[["Active count", "26+ specialised complementos"], ["Common examples", "Nómina 1.2 (payroll), Pagos 2.0 (instalments), Carta Porte 3.1 (freight)"], ["Structure", "Own namespace + validation rules, layered onto the base CFDI"]]', 'A CFDI for payroll or freight must satisfy Anexo 20 and its specific complemento''s technical annex simultaneously — these aren''t optional add-ons once your transaction type requires them.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'Mexico' AND dc.section = 'file_format' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'file_format', 2 FROM countries WHERE name_en = 'Mexico';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'en', 'Catalogs', '[["Types", "Uso CFDI, Régimen Fiscal, Productos y Servicios, Formas/Métodos de Pago"], ["Update cadence", "Periodic — typically annually"]]', 'Confirm your system or PAC has ingested the latest catalog version at the start of each fiscal year — using a retired code is one of the most common causes of stamping rejections.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'Mexico' AND dc.section = 'file_format' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'file_format', 3 FROM countries WHERE name_en = 'Mexico';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'en', 'Identity & signature', '[["Sello Digital", "Issuer''s own digital stamp"], ["PAC stamp", "Applied during timbrado"], ["Folio Fiscal", "UUID assigned at stamping — the permanent unique identifier"]]', 'The Folio Fiscal (UUID) is what every downstream system references — treat it the same way you''d treat Brazil''s chave de acesso or Italy''s SDI reference number.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'Mexico' AND dc.section = 'file_format' AND dc.sort_order = 3;

INSERT OR IGNORE INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'scope_transmission', 0 FROM countries WHERE name_en = 'Mexico';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'en', 'PACs — Proveedores Autorizados de Certificación', '[["Role", "SAT-authorised third parties that validate, stamp, and transmit CFDIs"], ["Pricing models", "Fractions of a peso per stamp at high volume; several pesos pay-as-you-go"], ["Complemento support", "Varies by provider — not every PAC supports every complemento"]]', 'Compare total cost of ownership at your actual monthly volume rather than headline per-stamp rates, and verify your chosen PAC genuinely supports every complemento your business needs (Carta Porte for freight, Comercio Exterior for international trade) before committing.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'Mexico' AND dc.section = 'scope_transmission' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'scope_transmission', 1 FROM countries WHERE name_en = 'Mexico';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'en', 'Rejection handling', '[["Common cause", "Retired catalog codes, mismatched receiver data"], ["Root cause pattern", "Manual data capture"]]', 'Modern invoicing platforms validate receiver data and catalog currency before ever reaching the PAC — automating this pre-check largely eliminates the most common rejection categories.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'Mexico' AND dc.section = 'scope_transmission' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'scope_transmission', 2 FROM countries WHERE name_en = 'Mexico';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'en', 'Correcting a CFDI', '[["Credit notes", "Governed by Apéndice 4 — correct \"tipo de relación\" code matters"], ["Common confusion", "01 (credit note) vs. 03 (merchandise return) vs. 07 (advance-payment application)"]]', 'Choosing the wrong relationship type code on a correction is a frequent source of downstream reconciliation problems — verify which of the three applies to your specific scenario before issuing.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'Mexico' AND dc.section = 'scope_transmission' AND dc.sort_order = 2;

