INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'en', '⚖️ Código Fiscal de la Federación framework', NULL, NULL, 'CFDI non-compliance is penalised under Mexico''s general federal tax code — including, in serious cases, closure of business premises (clausura) for repeated or severe infractions. Confirm current figures with a Mexican tax advisor given periodic revisions.', NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'Mexico' AND dc.section = 'penalties_related' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'penalties_related', 1 FROM countries WHERE name_en = 'Mexico';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'en', '🔍 Heightened scrutiny from 2026', NULL, NULL, 'The 2026 reform introduces criminal liability provisions for false or simulated CFDIs — this is a meaningfully sharper enforcement posture than prior years, worth flagging to finance leadership.', NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'Mexico' AND dc.section = 'penalties_related' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'penalties_related', 2 FROM countries WHERE name_en = 'Mexico';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'en', '👥 Multi-RFC complexity for accountants', NULL, NULL, 'Accounting firms managing many client RFCs face genuine operational complexity keeping catalog codes and complemento requirements current across every client — dedicated multi-RFC control tooling exists specifically for this reason.', NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'Mexico' AND dc.section = 'penalties_related' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'penalties_related', 3 FROM countries WHERE name_en = 'Mexico';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'en', '🚢 Complemento currency matters', NULL, NULL, 'SAT periodically updates individual complemento specifications (Carta Porte in particular has seen multiple version updates) — track your specific complemento versions separately from the base CFDI/Anexo 20 update cadence.', NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'Mexico' AND dc.section = 'penalties_related' AND dc.sort_order = 3;

